    const minutesInDay = 24 * 60;
    const normalized = ((totalMinutes % minutesInDay) + minutesInDay) % minutesInDay;
    const date = new Date();
    date.setHours(0, normalized, 0, 0);
    return date.toLocaleTimeString([], { hour: 'numeric' });
}

